{"cards": [{"node_code": "N_0229ae26485e0d43", "definition": "研究B淋巴细胞在抗原刺激下的活化、增殖、分化为浆细胞及分泌抗体的过程，涵盖体液免疫应答的机制、抗体多样性产生及免疫记忆形成。", "boundary": "本节点聚焦于B细胞介导的免疫反应，核心是抗体产生及其功能。包括B细胞受体识别、共刺激信号、生发中心反应及抗体类别转换。与“T细胞与细胞免疫”的区别在于，本节点侧重分泌抗体以中和或调理病原体，而非直接杀伤靶细胞；与父节点“适应性免疫”的区别在于，本节点特指B细胞谱系及体液效应，不包含T细胞介导的细胞毒性或辅助功能。", "includes": ["B细胞活化、分化及浆细胞产生抗体的机制", "抗体结构、功能及类别转换（Class Switching）", "体液免疫记忆及二次应答特征"], "excludes": ["T细胞介导的细胞毒性或辅助功能（归入T细胞与细胞免疫）", "非特异性免疫球蛋白的生理功能（若未涉及B细胞特异性应答）"], "sibling_distinctions": [{"other_code": "N_1aeac35e73091270", "rule": "B细胞与体液免疫侧重抗体分泌及体液效应；T细胞与细胞免疫侧重T细胞直接杀伤或辅助其他细胞，不产生抗体。"}], "cross_boundary_rule": "若研究T细胞辅助B细胞产生抗体的机制，主挂载B细胞与体液免疫（因最终效应为体液免疫）；若研究T细胞自身的活化与分化，主挂载T细胞与细胞免疫。"}, {"node_code": "N_1aeac35e73091270", "definition": "研究T淋巴细胞识别抗原肽-MHC复合物后的活化、克隆扩增及分化为效应T细胞（如细胞毒性T细胞、辅助T细胞）的过程，涵盖细胞免疫应答机制。", "boundary": "本节点聚焦于T细胞介导的免疫反应，核心是T细胞直接效应或辅助其他免疫细胞。包括CD4+辅助T细胞分泌细胞因子、CD8+细胞毒性T细胞杀伤感染细胞或肿瘤细胞。与“B细胞与体液免疫”的区别在于，本节点不产生抗体，而是通过细胞接触或细胞因子发挥作用；与父节点“适应性免疫”的区别在于，本节点特指T细胞谱系及其细胞效应，不包含B细胞介导的体液效应。", "includes": ["T细胞识别抗原、活化及分化为效应T细胞", "细胞毒性T细胞（CTL）杀伤机制", "辅助T细胞（Th）亚群分化及细胞因子分泌"], "excludes": ["B细胞活化及抗体产生（归入B细胞与体液免疫）", "固有免疫细胞（如NK细胞）的非特异性杀伤（归入固有免疫）"], "sibling_distinctions": [{"other_code": "N_0229ae26485e0d43", "rule": "T细胞与细胞免疫侧重T细胞直接杀伤或辅助功能；B细胞与体液免疫侧重抗体分泌及体液效应。"}], "cross_boundary_rule": "若研究T细胞辅助B细胞产生抗体的机制，主挂载B细胞与体液免疫（因最终效应为体液免疫）；若研究T细胞自身的活化与分化，主挂载T细胞与细胞免疫。"}]}
